/* eslint-disable node/no-sync */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Memory = require( '@stdlib/wasm/memory' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var Float64Array = require( '@stdlib/array/float64' );
var Module = require( './../lib' ).Module;


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Module, 'function', 'main export is a function' );
	t.end();
});

tape( 'a module instance has an `ndarray` method which has an arity of 8', function test( t ) {
	var mem;
	var mod;

	mem = new Memory({
		'initial': 0
	});
	mod = new Module( mem );
	t.strictEqual( mod.ndarray.length, 8, 'returns expected value' );
	t.end();
});

tape( 'a module instance has an `ndarray` method which calculates the arithmetic mean and population variance of a strided array', function test( t ) {
	var expected;
	var mem;
	var mod;
	var out;
	var xp;
	var y;

	mem = new Memory({
		'initial': 1
	});
	mod = new Module( mem );
	mod.initializeSync();

	xp = 0;

	mod.write( xp, new Float64Array( [ 1.0, -2.0, -4.0, 5.0, 0.0, 3.0 ] ) );

	out = new Float64Array( 2 );
	y = mod.ndarray( 6, 0, xp, 1, 0, out, 1, 0 );
	expected = new Float64Array( [ 0.5, 53.5/6 ] );
	t.strictEqual( y, out, 'returns expected value' );
	t.deepEqual( y, expected, 'returns expected value' );

	mod.write( xp, new Float64Array( [ -4.0, -4.0 ] ) );

	out = new Float64Array( 2 );
	y = mod.ndarray( 2, 0, xp, 1, 0, out, 1, 0 );
	expected = new Float64Array( [ -4.0, 0.0 ] );
	t.strictEqual( y, out, 'returns expected value' );
	t.deepEqual( y, expected, 'returns expected value' );

	mod.write( xp, new Float64Array( [ NaN, 4.0 ] ) );

	out = new Float64Array( 2 );
	y = mod.ndarray( 2, 0, xp, 1, 0, out, 1, 0 );
	t.strictEqual( y, out, 'returns expected value' );
	t.strictEqual( isnan( y[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( y[ 1 ] ), true, 'returns expected value' );

	t.end();
});

