tape( 'if provided an `N` parameter less than or equal to `0`, a module instance has an `ndarray` method which returns `NaN`', function test( t ) {
	var mem;
	var mod;
	var out;
	var xp;
	var y;

	mem = new Memory({
		'initial': 1
	});
	mod = new Module( mem );
	mod.initializeSync();

	xp = 0;

	mod.write( xp, new Float64Array( [ 1.0, -2.0, -4.0, 5.0, 0.0, 3.0 ] ) );

	out = new Float64Array( 2 );
	y = mod.ndarray( 0, 1, xp, 1, 0, out, 1, 0 );
	t.strictEqual( isnan( y[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( y[ 1 ] ), true, 'returns expected value' );

	out = new Float64Array( 2 );
	y = mod.ndarray( -1, 1, xp, 1, 0, out, 1, 0 );
	t.strictEqual( isnan( y[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( y[ 1 ] ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided an `N` parameter equal to `1`, a module instance has an `ndarray` method which returns a population variance of `0`', function test( t ) {
	var expected;
	var mem;
	var mod;
	var out;
	var xp;
	var y;

	mem = new Memory({
		'initial': 1
	});
	mod = new Module( mem );
	mod.initializeSync();

	xp = 0;

	mod.write( xp, new Float64Array( [ 1.0, -2.0, -4.0, 5.0, 0.0, 3.0 ] ) );

	out = new Float64Array( 2 );
	y = mod.ndarray( 1, 0, xp, 1, 0, out, 1, 0 );
	expected = new Float64Array( [ 1.0, 0.0 ] );
	t.deepEqual( y, expected, 'returns expected value' );

	t.end();
});

tape( 'if provided a `correction` parameter yielding `N-correction` less than or equal to `0`, a module instance has an `ndarray` method which returns a variance equal to `NaN`', function test( t ) {
	var mem;
	var mod;
	var out;
	var xp;
	var y;

	mem = new Memory({
		'initial': 1
	});
	mod = new Module( mem );
	mod.initializeSync();

	xp = 0;

	mod.write( xp, new Float64Array( [ 1.0, -2.0, -4.0, 5.0, 0.0, 3.0 ] ) );

	out = new Float64Array( 2 );
	y = mod.ndarray( 1, 1, xp, 1, 0, out, 1, 0 );
	t.strictEqual( y[ 0 ], 1.0, 'returns expected value' );
	t.strictEqual( isnan( y[ 1 ] ), true, 'returns expected value' );

	out = new Float64Array( 2 );
	y = mod.ndarray( 6, 6, xp, 0, 0, out, 1, 0 );
	t.strictEqual( y[ 0 ], 1.0, 'returns expected value' );
	t.strictEqual( isnan( y[ 1 ] ), true, 'returns expected value' );

	out = new Float64Array( 2 );
	y = mod.ndarray( 6, 6, xp, 1, 0, out, 1, 0 );
	t.strictEqual( y[ 0 ], 0.5, 'returns expected value' );
	t.strictEqual( isnan( y[ 1 ] ), true, 'returns expected value' );

	out = new Float64Array( 2 );
	y = mod.ndarray( 6, 7, xp, 1, 0, out, 1, 0 );
	t.strictEqual( y[ 0 ], 0.5, 'returns expected value' );
	t.strictEqual( isnan( y[ 1 ] ), true, 'returns expected value' );

	t.end();
});

tape( 'a module instance has an `ndarray` method which supports a `stride` parameter', function test( t ) {
	var expected;
	var mem;
	var mod;
	var out;
	var xp;
	var y;

	mem = new Memory({
		'initial': 1
	});
	mod = new Module( mem );
	mod.initializeSync();

	xp = 0;

	mod.write( xp, new Float64Array([
		1.0,  // 0
		2.0,
		2.0,  // 1
		-7.0,
		-2.0, // 2
		3.0,
		4.0,  // 3
		2.0
	]));
	out = new Float64Array( 4 );

	y = mod.ndarray( 4, 1, xp, 2, 0, out, 2, 0 );
	expected = new Float64Array( [ 1.25, 0.0, 6.25, 0.0 ] );
	t.deepEqual( y, expected, 'returns expected value' );

	t.end();
});

tape( 'a module instance has an `ndarray` method which supports a negative `stride` parameter', function test( t ) {
	var expected;
	var mem;
	var mod;
	var out;
	var xp;
	var y;

	mem = new Memory({
		'initial': 1
	});
	mod = new Module( mem );
	mod.initializeSync();

	xp = 0;

	mod.write( xp, new Float64Array([
		1.0,  // 3
		2.0,
		2.0,  // 2
		-7.0,
		-2.0, // 1
		3.0,
		4.0,  // 0
		2.0
	]));
	out = new Float64Array( 4 );

	y = mod.ndarray( 4, 1, xp, -2, 6, out, -2, 2 );
	expected = new Float64Array( [ 6.25, 0.0, 1.25, 0.0 ] );
	t.deepEqual( y, expected, 'returns expected value' );

	t.end();
});

