tape( 'a module instance has an `ndarray` method which supports `offset` parameters', function test( t ) {
	var expected;
	var mem;
	var mod;
	var out;
	var xp;
	var y;

	mem = new Memory({
		'initial': 1
	});
	mod = new Module( mem );
	mod.initializeSync();

	xp = 0;

	mod.write( xp, new Float64Array([
		2.0,
		1.0,  // 0
		2.0,
		-2.0, // 1
		-2.0,
		2.0,  // 2
		3.0,
		4.0   // 3
	]));
	out = new Float64Array( 4 );

	y = mod.ndarray( 4, 1, xp, 2, 1, out, 2, 1 );
	expected = new Float64Array( [ 0.0, 1.25, 0.0, 6.25 ] );
	t.deepEqual( y, expected, 'returns expected value' );

	t.end();
});
